import sys

def ask(c, d):
    print(f"? {c} {d}")
    sys.stdout.flush()
    try:
        line = sys.stdin.readline()
        if not line:
            return -2
        res = int(line.strip())
        return res
    except:
        return -2

def solve():
    a = 0
    b = 0
    diff = 0
    for i in range(29, -1, -1):
        mask = 1 << i
        c = a | mask
        d = b
        res = ask(c, d)
        if res == -2:
            break
        if res == 1:
            pass
        elif res == -1:
            a |= mask
        else:
            b |= mask

    if ask(a, b) == -2:
        return

    print(f"! {a} {b}")
    sys.stdout.flush()

if __name__ == "__main__":
    solve()
